'use strict';
const motion = matchMedia('(prefers-reduced-motion: reduce)');
const menuButton = document.querySelector('.menu-toggle');
const mobileNav = document.querySelector('.mobile-nav');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Ouvrir le menu');mobileNav.classList.remove('open');mobileNav.inert=true;document.body.classList.remove('menu-open');}
menuButton.addEventListener('click',()=>{const opening=menuButton.getAttribute('aria-expanded')!=='true';if(!opening){closeMenu();return;}menuButton.setAttribute('aria-expanded','true');menuButton.setAttribute('aria-label','Fermer le menu');mobileNav.inert=false;mobileNav.classList.add('open');document.body.classList.add('menu-open');mobileNav.querySelector('a').focus();});
mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(menuButton.getAttribute('aria-expanded')!=='true')return;if(e.key==='Escape'){closeMenu();menuButton.focus();}if(e.key==='Tab'){const links=[menuButton,...mobileNav.querySelectorAll('a')];let i=links.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();links.at(-1).focus();}else if(!e.shiftKey&&i===links.length-1){e.preventDefault();menuButton.focus();}}});
matchMedia('(min-width:761px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
if('IntersectionObserver' in window){if(!motion.matches)document.documentElement.classList.add('js-motion');const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));}
const hero=document.querySelector('.hero');const scene=document.querySelector('.hero-image');let mouseFrame=0;
hero.addEventListener('pointermove',e=>{if(motion.matches||e.pointerType!=='mouse'||innerWidth<761)return;cancelAnimationFrame(mouseFrame);mouseFrame=requestAnimationFrame(()=>{const rect=hero.getBoundingClientRect();const x=(e.clientX/rect.width-.5)*10;const y=((e.clientY-rect.top)/rect.height-.5)*6;scene.style.transform=`translate3d(${x}px,${y}px,0)`;});});
hero.addEventListener('pointerleave',()=>{cancelAnimationFrame(mouseFrame);scene.style.transform='';});
const canvas=document.querySelector('#sound-canvas');const ctx=canvas.getContext('2d');let width=0,height=0,frame=0,visible=false;
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw(0);}
function draw(time){ctx.clearRect(0,0,width,height);const cx=width/2,cy=height/2;for(let i=0;i<25;i++){ctx.beginPath();const radius=width*(.085+i*.014);for(let j=0;j<=160;j++){const a=j/160*Math.PI*2;const wave=Math.sin(a*3+time*.0003+i*.2)*width*.010+Math.sin(a*5-time*.0002)*width*.004;const x=cx+Math.cos(a)*(radius+wave);const y=cy+Math.sin(a)*(radius+wave)*.91;if(j===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.closePath();ctx.strokeStyle=`rgba(58,68,59,${.06+Math.sin(i/25*Math.PI)*.22})`;ctx.lineWidth=.7;ctx.stroke();}ctx.strokeStyle='rgba(62,72,63,.14)';ctx.setLineDash([2,8]);ctx.beginPath();ctx.moveTo(cx,cy-height*.38);ctx.lineTo(cx,cy+height*.38);ctx.moveTo(cx-width*.38,cy);ctx.lineTo(cx+width*.38,cy);ctx.stroke();ctx.setLineDash([]);}
function tick(time){draw(time);if(visible&&!motion.matches&&!document.hidden)frame=requestAnimationFrame(tick);else frame=0;}
function syncAnimation(){cancelAnimationFrame(frame);frame=0;if(visible&&!motion.matches&&!document.hidden)frame=requestAnimationFrame(tick);else draw(0);}
new ResizeObserver(resize).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;syncAnimation();}).observe(canvas);document.addEventListener('visibilitychange',syncAnimation);motion.addEventListener('change',()=>{document.documentElement.classList.toggle('js-motion',!motion.matches);scene.style.transform='';syncAnimation();});
